import { precacheAndRoute } from 'workbox-precaching';
import { registerRoute } from 'workbox-routing';
import { StaleWhileRevalidate, CacheFirst, NetworkFirst } from 'workbox-strategies';
import { ExpirationPlugin } from 'workbox-expiration';
import { CacheableResponsePlugin } from 'workbox-cacheable-response';

declare let self: ServiceWorkerGlobalScope & { __WB_MANIFEST: any };

// Precache all assets generated by Vite
precacheAndRoute(self.__WB_MANIFEST);

const CACHE_NAME = 'caruban-core-v3';
const MEMBER_DATA_CACHE = 'caruban-member-data-v3';
const MAP_TILES_CACHE = 'map-tiles-v3';

// 1. Handle Map Tiles (CartoDB / OpenStreetMap) for offline maps
registerRoute(
  ({ url }) => url.href.includes('basemaps.cartocdn.com') || url.href.includes('tile.openstreetmap.org'),
  new CacheFirst({
    cacheName: MAP_TILES_CACHE,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 500,
        maxAgeSeconds: 30 * 24 * 60 * 60, // 30 Days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  })
);

// 2. Member data API calls or offline endpoint requests
registerRoute(
  ({ url }) => url.pathname.includes('/offline-cache/critical-members.json') || url.pathname.includes('/api/members'),
  new NetworkFirst({
    cacheName: MEMBER_DATA_CACHE,
    plugins: [
      new ExpirationPlugin({
        maxEntries: 10,
        maxAgeSeconds: 7 * 24 * 60 * 60, // 7 Days
      }),
      new CacheableResponsePlugin({
        statuses: [0, 200],
      }),
    ],
  })
);

// 3. Static assets & navigation requests (Stale-While-Revalidate for app shell if not in precache)
registerRoute(
  ({ request }) => request.destination === 'style' || request.destination === 'script' || request.destination === 'worker',
  new StaleWhileRevalidate({
    cacheName: 'static-resources',
  })
);

// Custom Message event for manual member caching from UI
self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'CACHE_CRITICAL_MEMBER_DATA') {
    const memberData = event.data.payload;
    caches.open(MEMBER_DATA_CACHE).then((cache) => {
      const response = new Response(JSON.stringify(memberData), {
        headers: {
          'Content-Type': 'application/json',
          'X-Caruban-Cache-Time': new Date().toISOString(),
          'X-Caruban-Count': String(Array.isArray(memberData) ? memberData.length : 0)
        }
      });
      cache.put('/offline-cache/critical-members.json', response);
      console.log(`[SW] Cached ${Array.isArray(memberData) ? memberData.length : 1} critical member records for offline visits.`);
    });
  }

  if (event.data && event.data.type === 'GET_OFFLINE_CACHE_STATUS') {
    caches.open(MEMBER_DATA_CACHE).then(async (cache) => {
      const res = await cache.match('/offline-cache/critical-members.json');
      const count = res ? res.headers.get('X-Caruban-Count') || '0' : '0';
      const time = res ? res.headers.get('X-Caruban-Cache-Time') || null : null;
      if (event.source) {
        (event.source as Client).postMessage({
          type: 'OFFLINE_CACHE_STATUS',
          count: parseInt(count, 10),
          lastUpdated: time
        });
      }
    });
  }
  
  if (event.data && event.data.type === 'SKIP_WAITING') {
    self.skipWaiting();
  }
});

// Push Notification Handling
self.addEventListener('push', (event: any) => {
  if (event.data) {
    try {
      const data = event.data.json();
      const options = {
        body: data.body,
        icon: '/favicon.ico',
        badge: '/favicon.ico',
        data: data.url || '/',
        vibrate: [100, 50, 100],
        actions: [
          { action: 'open', title: 'Buka Aplikasi' }
        ]
      };
      event.waitUntil(
        self.registration.showNotification(data.title, options)
      );
    } catch (e) {
      console.error('Error parsing push data:', e);
    }
  }
});

self.addEventListener('notificationclick', (event: any) => {
  event.notification.close();
  const urlToOpen = event.notification.data || '/';
  
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then((windowClients) => {
      for (let client of windowClients) {
        if (client.url === urlToOpen && 'focus' in client) {
          return client.focus();
        }
      }
      if (self.clients.openWindow) {
        return self.clients.openWindow(urlToOpen);
      }
    })
  );
});

// Background Sync for Offline Data
self.addEventListener('sync', (event: any) => {
  if (event.tag === 'sync-members') {
    console.log('[SW] Background sync triggered for members');
    event.waitUntil(syncMembersData());
  }
});


async function syncMembersData() {
  try {
    const response = await fetch('/api/members');
    if (!response.ok) throw new Error('Network response was not ok');
    const data = await response.json();
    const cache = await caches.open(MEMBER_DATA_CACHE);
    const timestamp = new Date().toISOString();
    const cacheResponse = new Response(JSON.stringify(data), {
      headers: {
        'Content-Type': 'application/json',
        'X-Caruban-Cache-Time': timestamp,
        'X-Caruban-Count': String(data.length)
      }
    });
    await cache.put('/offline-cache/critical-members.json', cacheResponse);
    console.log('[SW] Background sync successful');
  } catch (err) {
    console.error('[SW] Background sync failed', err);
  }
}
